import base64,hashlib,json,pathlib,subprocess,os,tarfile
os.umask(0o077)
commit='b6a5f9bec9cd506752112c5107881b1e55d0b334'
base='7da24b0d2bf75e987c5aaaa092a0d60acc784055'
mode='apply'
script_bytes=base64.b64decode('')
expected_tool='5cc4fd020ee8d6f62c0cae25e86a77b45fbcad9023db206603ab9a7f4eff4793'
expected_archive='bf49953f76ad9e848de7f0027635f15faf287a9fa8ff6deb39525725f1d2f250'
expected_manifest='8628838d9cd55efc3af2215b07363873443339ed91c9afdfa078d487d648d7be'
expected_profile='d30b66cc270f1f8868207f80539d9e0b6b486bdbd1cca24abde32d56fd17e98e'
root=pathlib.Path('/opt/tp-community-actions')
archive=root/'incoming'/('control-plane-frontend-'+commit+'.tar.gz')
tools=root/'qa-frontend-tools'
path=tools/('release-'+commit+'.py')
def digest(path):
 h=hashlib.sha256()
 with path.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
result={'operation':'frontend-detail-route-'+mode,'commit':commit,'base':base,'tool_sha256':expected_tool}
try:
 assert hashlib.sha256(script_bytes).hexdigest()==expected_tool
 assert archive.is_file() and not archive.is_symlink()
 result['archive_sha256']=digest(archive)
 if expected_archive:assert result['archive_sha256']==expected_archive,'Candidate archive changed after plan'
 if mode=='apply':assert expected_archive,'Apply requires the reviewed plan archive hash'
 with tarfile.open(str(archive)) as tar:
  files={};total=0
  for member in tar.getmembers():
   name=pathlib.PurePosixPath(member.name)
   assert not name.is_absolute() and '..' not in name.parts and (member.isfile() or member.isdir()),'Unsafe archive member'
   if member.isfile():
    assert member.name not in files,'Duplicate archive member'
    files[member.name]=member;total+=member.size
  manifest_bytes=tar.extractfile(files['manifest.json']).read()
  assert hashlib.sha256(manifest_bytes).hexdigest()==expected_manifest,'CI manifest changed'
  manifest=json.loads(manifest_bytes)
  assert manifest['commit']==commit and manifest['profile']=='control-plane'
  assert set(files)==set(manifest['sha256'])|{'manifest.json'},'Unexpected archive files'
  for name,wanted in manifest['sha256'].items():
   assert hashlib.sha256(tar.extractfile(files[name]).read()).hexdigest()==wanted,'Archive file differs from CI manifest'
  assert tar.extractfile(files['SOURCE_COMMIT']).read()==(commit+'\n').encode()
  profile_bytes=tar.extractfile(files['RELEASE_PROFILE.json']).read()
  assert hashlib.sha256(profile_bytes).hexdigest()==expected_profile
  profile=json.loads(profile_bytes)
  assert profile['source_commit']==commit and len(profile['overrides'])==33 and len(profile['device_ui_patches'])==4
  result.update(manifest_sha256=expected_manifest,profile_sha256=expected_profile,validated_files=len(files),expanded_bytes=total)
 tools.mkdir(exist_ok=True,mode=0o700)
 assert not path.is_symlink()
 if path.exists():assert digest(path)==expected_tool
 else:path.write_bytes(script_bytes)
 args=['/usr/bin/python3.11',str(path)]
 if mode=='apply':args+=['--apply','--bundle',str(archive),'--bundle-sha256',expected_archive]
 process=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=150)
 result['exit_code']=process.returncode
 if process.returncode:result.update(status='FAIL',error=process.stderr.strip().splitlines()[-1] if process.stderr.strip() else 'operation failed')
 else:result.update(status='PASS',result=json.loads(process.stdout))
except Exception as error:result.update(status='FAIL',error=type(error).__name__+': '+str(error))
print(json.dumps(result))
